/**
 * Decorative, whole-quadrant bubble cover. The caller owns the accessible
 * button, the concealed result, and reveal state. Load styles/bubble-reveal.css.
 */
const POP_DURATION_MS = 220;

function span(doc, suffix) {
  const node = doc.createElement('span');
  node.className = `bubble-reveal__${suffix}`;
  return node;
}

function createBadgeOptics(doc) {
  // Identical optics share one cached SVG instead of mounting 20 extra styled
  // nodes for every bubble (2,000 nodes in a 25-card reveal).
  const art = doc.createElement('img');
  art.className = 'bubble-reveal__badge-optics';
  art.src = '/app/assets/bubble-badge-optics-v1.svg';
  art.alt = '';
  art.draggable = false;
  return art;
}

/** Shared champion aura. The legacy export name keeps cached callers compatible. */
export function createHeroCrown(doc) {
  const frame = span(doc, 'hero');
  frame.setAttribute('aria-hidden', 'true');
  const art = doc.createElement('img');
  art.src = '/app/assets/degenerette/champion-aura-v2.svg';
  art.alt = '';
  art.draggable = false;
  frame.appendChild(art);
  return frame;
}

/**
 * @param {Document} doc
 * @param {{badgeSrc: string, color?: string, hero?: boolean, durationMs?: number}} options
 * @returns {{element: HTMLSpanElement, pop: Function, dispose: Function}}
 *
 * Pop is one-way and idempotent. Its completion removes the cover before
 * invoking onComplete. Instant/reduced-motion pops complete synchronously.
 * `pop(event, { batch: true })` uses a geometry-free grouped transition.
 * dispose() removes it and cancels any pending completion.
 */
export function createBubbleCover(doc, { badgeSrc, color, hero = false, durationMs = POP_DURATION_MS } = {}) {
  const view = doc.defaultView || globalThis;
  const schedule = (view.setTimeout || globalThis.setTimeout).bind(view);
  const cancel = (view.clearTimeout || globalThis.clearTimeout).bind(view);
  const duration = Number.isFinite(durationMs) && durationMs > 0 ? durationMs : POP_DURATION_MS;
  const element = doc.createElement('span');
  element.className = 'bubble-reveal';
  element.setAttribute('aria-hidden', 'true');
  element.style.setProperty('--bubble-reveal-duration', `${duration}ms`);
  if (color) element.style.setProperty('--bubble-reveal-color', color);

  const film = span(doc, 'film');
  for (const part of ['skin', 'dent', 'glint']) film.appendChild(span(doc, part));
  const badge = span(doc, 'badge');
  const art = doc.createElement('img');
  art.className = 'bubble-reveal__badge-art';
  art.alt = '';
  art.draggable = false;
  if (badgeSrc) art.src = badgeSrc;
  badge.appendChild(art);
  badge.appendChild(createBadgeOptics(doc));
  film.appendChild(badge);
  film.appendChild(span(doc, 'lowlight'));
  element.appendChild(film);
  element.appendChild(span(doc, 'burst'));
  if (hero) element.appendChild(createHeroCrown(doc));

  let state = 'covered';
  let timer = null;

  function pop(event, { instant = false, batch = false, onComplete = () => {} } = {}) {
    if (state !== 'covered') return false;
    state = 'popping';

    const finish = () => {
      if (state !== 'popping') return;
      timer = null;
      state = 'complete';
      element.remove();
      onComplete();
    };
    if (instant || view.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      finish();
      return true;
    }

    // Whole-card/mass reveals use one short compositor transition. They need
    // no geometry, animated mask, or inherited aperture updates per quadrant.
    if (batch) {
      element.classList.add('is-batch-pop', 'is-popping');
      timer = schedule(finish, duration);
      return true;
    }

    const pointer = event?.detail > 0
      && Number.isFinite(event.clientX) && Number.isFinite(event.clientY);
    // Keyboard/programmatic pops are centred and need no layout read.
    const bounds = pointer ? element.getBoundingClientRect() : null;
    const clamp = value => Math.max(0, Math.min(1, value));
    const x = bounds?.width > 0 ? clamp((event.clientX - bounds.left) / bounds.width) : .5;
    const y = bounds?.height > 0 ? clamp((event.clientY - bounds.top) / bounds.height) : .5;
    element.style.setProperty('--bubble-reveal-pop-x', `${x * 100}%`);
    element.style.setProperty('--bubble-reveal-pop-y', `${y * 100}%`);
    // The decorative ripple overscans the cover; percent sizing also works
    // under scaled tickets without measuring their untransformed layout.
    element.style.setProperty('--bubble-reveal-pop-radius', '142%');
    element.style.setProperty('--bubble-reveal-lip-start', '.02');
    element.classList.add('is-popping');
    timer = schedule(finish, duration);
    return true;
  }

  function dispose() {
    if (timer !== null) cancel(timer);
    timer = null;
    state = 'disposed';
    element.remove();
  }

  return { element, pop, dispose };
}
